package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamTensesBank2 {
  private const val T = "Tenses: Past Forms & Sequence of Tenses"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("Yesterday evening, we ___ a documentary about Sinharaja rainforest.", "watched", "watch", "watching", "have watch", "'Yesterday evening' specifies finished past time -> Simple Past 'watched'."),
    q("Two days ago, my cousin ___ a medal in the provincial athletic meet.", "won", "wins", "winning", "has won", "'Two days ago' demands Simple Past 'won'."),
    q("In 1948, Sri Lanka ___ independence from British rule.", "gained", "gains", "has gained", "was gain", "Specific historical year 'In 1948' takes Simple Past 'gained'."),
    q("Did you ___ the science museum during your holiday in Colombo?", "visit", "visited", "visiting", "visits", "After 'Did', use the base verb 'visit'."),
    q("Kamal didn't ___ his lunch box to school yesterday morning.", "bring", "brought", "bringing", "brings", "Negative 'didn't' always pairs with base verb 'bring'."),
    q("Where did the scouts ___ their tents last weekend?", "pitch", "pitched", "pitching", "pitches", "Question 'did + subject' takes base verb 'pitch'."),
    q("She ___ a wonderful short story for the school magazine last month.", "wrote", "write", "written", "writing", "Simple Past of 'write' is 'wrote'."),
    q("Who ___ the broken window pane in the science lab yesterday?", "broke", "break", "broken", "breaking", "Simple Past of 'break' is 'broke'."),
    q("The little boy ___ off his bicycle and hurt his knee.", "fell", "fall", "fallen", "felt", "Simple Past of 'fall' is 'fell' ('felt' is past of 'feel')."),
    q("I ___ my lost spectacles under the sofa this morning.", "found", "find", "founded", "finding", "Past of 'find' is 'found' ('founded' means established)."),
    q("King Parakramabahu ___ the great Parakrama Samudra tank.", "built", "build", "builded", "building", "Irregular past of 'build' is 'built'."),
    q("The speaker ___ clearly and inspired the entire audience.", "spoke", "speak", "spoken", "speaking", "Past simple of 'speak' is 'spoke'."),
    q("They ___ across the calm lagoon in a small wooden boat.", "swam", "swim", "swum", "swimming", "Past simple of 'swim' is 'swam'."),
    q("Mother ___ fresh vegetables from the Sunday fair.", "bought", "buy", "brought", "buying", "Past simple of 'buy' is 'bought'."),
    q("Mr. Perera ___ mathematics to Grade 10 students for thirty years before retiring.", "taught", "teach", "teached", "teaching", "Past simple of 'teach' is 'taught'."),
    q("While I ___ studying, the electricity suddenly went off.", "was", "am", "were", "had", "Ongoing past background action uses 'was + V-ing'."),
    q("They ___ having dinner when the unexpected visitors knocked.", "were", "was", "are", "had", "Plural 'They' in Past Continuous takes 'were'."),
    q("While Father was washing the car, Mother ___ planting orchids.", "was", "were", "is", "had", "Two parallel ongoing past actions both use Past Continuous."),
    q("What ___ you doing at 7:30 p.m. last night?", "were", "was", "did", "are", "With 'you' in Past Continuous, always use 'were'."),
    q("As the girl ___ crossing the street, she noticed a stray puppy.", "was", "were", "is", "had", "Interrupted past action takes 'was crossing'."),
    q("While the choir was singing, the lights ___ out briefly.", "went", "were going", "go", "had go", "A short interrupting past event uses Simple Past 'went'."),
    q("When I arrived at the hall, the drama ___ already started.", "had", "has", "was", "did", "Action completed before another past point takes Past Perfect 'had'."),
    q("By the time the fire engine arrived, villagers ___ put out the fire.", "had", "have", "were", "did", "Earlier of two past actions takes Past Perfect 'had'."),
    q("After she ___ finished her homework, she went out to play.", "had", "has", "was", "did", "'After + Past Perfect' shows the earlier completed past action."),
    q("The train had already ___ before we reached the railway platform.", "left", "leave", "leaving", "leaves", "Past Perfect uses 'had + past participle (left)'."),
    q("He told me that he ___ never seen such a large elephant before.", "had", "has", "was", "did", "Reported earlier experience uses Past Perfect 'had'."),
    q("She realized she had ___ her admission card at home.", "forgotten", "forgot", "forget", "forgetting", "Past participle of 'forget' after 'had' is 'forgotten'."),
    q("We ___ been waiting for forty minutes before the bus finally came.", "had", "have", "were", "are", "Duration up to a past moment takes Past Perfect Continuous 'had been'."),
    q("Her eyes were red because she had ___ peeling onions.", "been", "being", "be", "was", "Past evidence caused by prior ongoing activity uses 'had been + V-ing'."),
    q("The farmer was tired as he ___ been ploughing the field since dawn.", "had", "has", "was", "did", "Ongoing action before a past moment uses 'had been'."),
    q("My grandfather ___ to walk five miles to school in his youth.", "used", "use", "using", "was use", "Past habit no longer true uses 'used to + base verb'."),
    q("Did your parents ___ to live in Anuradhapura long ago?", "use", "used", "using", "uses", "In questions with 'Did', drop the 'd': 'Did ... use to'."),
    q("I didn't ___ to like bitter gourd, though I enjoy it now.", "use", "used", "using", "uses", "In negatives with 'didn't', use 'use to' without 'd'."),
    q("Every holiday, our uncle ___ tell us fascinating folk tales.", "would", "used", "will", "has", "'Would + V1' expresses repeated past habits in storytelling."),
    q("Hardly had we stepped outside ___ it began to drizzle.", "when", "than", "that", "then", "'Hardly had...' always correlates with 'when'."),
    q("No sooner had the bell rung ___ the students lined up neatly.", "than", "when", "then", "that", "'No sooner had...' always correlates with 'than'."),
    q("Scarcely had the concert started ___ a power cut occurred.", "when", "than", "as", "until", "'Scarcely had...' takes 'when'."),
    q("I ___ my friend Nimal in town three weeks ago.", "met", "have met", "meet", "had meet", "Finished past time marker 'ago' takes Simple Past 'met'."),
    q("Last year, our school ___ the all-island debating championship.", "won", "has won", "wins", "was win", "'Last year' takes Simple Past 'won'."),
    q("The child ___ quietly because he had lost his favourite toy.", "wept", "weep", "weeped", "weeping", "Irregular past of 'weep' is 'wept'."),
    q("Suddenly, a loud clap of thunder ___ the quiet night.", "shook", "shake", "shaken", "shaking", "Irregular past of 'shake' is 'shook'."),
    q("She ___ the heavy glass vase carefully onto the wooden shelf.", "set", "setted", "setting", "sets", "'Set' remains 'set' in Simple Past and Past Participle."),
    q("Yesterday, the tailor ___ a neat uniform for the new prefect.", "sewed", "sew", "sow", "sewing", "Past simple of 'sew' is 'sewed' ('sow' means plant seeds)."),
    q("The river ___ over its banks after three days of monsoon rain.", "overflowed", "overflow", "overflew", "overflowing", "Past tense of 'overflow' is 'overflowed' (not 'overflew')."),
    q("A huge flock of birds ___ southward across the sunset sky.", "flew", "flowed", "fly", "flown", "Past of 'fly' is 'flew' ('flowed' is past of 'flow')."),
    q("The gentle stream ___ cleanly past the village temple.", "flowed", "flew", "flown", "flowing", "Past of 'flow' is 'flowed'."),
    q("He ___ down on the grass for a short rest after weeding.", "lay", "laid", "lied", "lying", "Past simple of 'lie' (recline) is 'lay'."),
    q("The hen ___ three fresh eggs in the coop yesterday.", "laid", "lay", "lain", "lied", "Past simple of 'lay' (place/produce eggs) is 'laid'."),
    q("Unfortunately, the witness ___ to the police about the time.", "lied", "lay", "laid", "lain", "Past simple of 'lie' (tell untruth) is 'lied'."),
    q("The carpenter ___ the old timber fence along the boundary.", "sawed", "saw", "seen", "sawing", "Past of verb 'saw' (cut with a saw) is 'sawed'."),
    q("We ___ a rare leopard resting on a rock at Yala.", "saw", "seen", "sawed", "seeing", "Past of 'see' is 'saw'."),
    q("He ___ a deep breath before starting his welcome speech.", "took", "take", "taken", "taking", "Simple Past of 'take' is 'took'."),
    q("The cold wind ___ sharply through the open corridor last night.", "blew", "blow", "blown", "blowing", "Simple Past of 'blow' is 'blew'."),
    q("Amali ___ her best friend a lovely handmade birthday card.", "gave", "give", "given", "giving", "Simple Past of 'give' is 'gave'."),
    q("Who ___ you this interesting book on ancient Sri Lanka?", "lent", "lend", "lended", "lending", "Past simple of 'lend' is 'lent'."),
    q("The frightened deer ___ rapidly into the thick jungle.", "ran", "run", "running", "runs", "Simple Past of 'run' is 'ran'."),
    q("Nobody ___ the correct answer during the first round.", "knew", "know", "known", "knowing", "Simple Past of 'know' is 'knew'."),
    q("She ___ her ankle while running down the wet steps.", "sprained", "sprain", "spraining", "sprains", "Regular past of 'sprain' is 'sprained'."),
    q("I ___ reading a novel when my friend phoned me.", "was", "am", "were", "have", "Ongoing past action interrupted by a phone call uses 'was'."),
    q("The students ___ quietly taking notes while the lecturer spoke.", "were", "was", "are", "had", "Plural 'students' in Past Continuous takes 'were'."),
    q("At eight last night, we ___ watching the news bulletin.", "were", "was", "are", "have", "Plural 'we' in Past Continuous takes 'were'."),
    q("Was the gardener ___ the flower beds when it started raining?", "watering", "water", "watered", "waters", "Past Continuous question uses 'Was + subject + V-ing'."),
    q("Before he moved to Galle, he ___ worked in Matara for five years.", "had", "has", "was", "is", "Earlier past period prior to another past move takes 'had'."),
    q("They didn't go to the cinema because they had already ___ the film.", "seen", "saw", "see", "seeing", "Past Perfect uses 'had + V3 (seen)'."),
    q("Until last year, I had never ___ an elephant in the wild.", "seen", "saw", "see", "seeing", "'Until last year' + 'never' requires Past Perfect 'had seen'."),
    q("She looked delighted because she ___ passed with nine distinctions.", "had", "has", "is", "will", "Cause completed before past state 'looked' takes 'had'."),
    q("After the sun had ___, the villagers returned to their homes.", "set", "sat", "sit", "setting", "Past participle of 'set' (go down) is 'set'."),
    q("The guests ___ just left when the thunderstorm broke out.", "had", "have", "were", "are", "Action completed just before another past event uses 'had'."),
    q("When the teacher entered, the class ___ already become silent.", "had", "has", "was", "is", "Completed prior to 'entered' requires Past Perfect 'had'."),
    q("How long had they been ___ before the rescue boat arrived?", "rowing", "row", "rowed", "rows", "Past Perfect Continuous requires 'had been + V-ing'."),
    q("He ___ been saving money for months before he bought the guitar.", "had", "has", "was", "is", "Continuous action leading up to a past purchase uses 'had'."),
    q("Before electricity reached the village, people ___ oil lamps.", "used", "use", "using", "are using", "Historical past state takes Simple Past 'used'."),
    q("We ___ to visit the Perahera every August when we were kids.", "used", "use", "using", "were use", "Repeated past childhood habit takes 'used to'."),
    q("She promised that she ___ write to us as soon as she arrived.", "would", "will", "shall", "can", "Future-in-the-past after 'promised' shifts 'will' to 'would'."),
    q("He said he ___ never tasted such sweet mangoes before.", "had", "has", "was", "is", "Reported past experience shifts to Past Perfect 'had'."),
    q("The teacher asked whether everyone ___ understood the poem.", "had", "has", "was", "is", "Indirect past question backshifts to 'had understood'."),
    q("I thought you ___ coming to the debate practice yesterday.", "were", "are", "will", "had", "Reported past continuous shifts 'are' to 'were'."),
    q("Once the rain stopped, the children ___ out to fly kites.", "rushed", "rush", "rushing", "have rush", "Sequential past events both use Simple Past."),
    q("He unlocked the door, stepped inside, and ___ on the light.", "switched", "switch", "switching", "switches", "Series of past actions share Simple Past tense."),
    q("The goalkeeper ___ the fast shot and saved the match.", "caught", "catch", "catched", "catching", "Irregular past of 'catch' is 'caught'."),
    q("She ___ her old textbooks neatly onto the lower shelf.", "put", "putted", "putting", "puts", "'Put' is invariable in Simple Past."),
    q("The tailor ___ the silk cloth accurately before stitching.", "cut", "cutted", "cutting", "cuts", "'Cut' keeps the same form in Simple Past."),
    q("Last Monday, the principal ___ an inspiring assembly speech.", "delivered", "deliver", "delivers", "delivering", "'Last Monday' indicates Simple Past 'delivered'."),
    q("When I was ten years old, I ___ my leg playing rugby.", "hurt", "hurted", "hurting", "hurts", "Simple Past of 'hurt' is 'hurt'."),
    q("The strong wind ___ away several dry leaves from the yard.", "swept", "sweep", "sweeped", "sweeping", "Irregular past of 'sweep' is 'swept'."),
    q("Have you ___ your umbrella? No, I ___ it in the bus yesterday.", "lost / left", "lose / leave", "lost / leave", "lose / left", "First uses Present Perfect V3 ('lost'); second uses Simple Past ('left')."),
    q("She ___ a lovely song when I walked into the music room.", "was singing", "sings", "sang", "is singing", "Action already in progress at a past arrival uses 'was singing'."),
    q("While they were cleaning the garden, they ___ an old coin.", "found", "were finding", "find", "are finding", "Shorter event interrupting a longer background action uses Simple Past."),
    q("By 2020, the town ___ grown into a busy commercial hub.", "had", "has", "was", "is", "'By + past year' indicates completion before then: Past Perfect 'had'."),
    q("By the time we finished dinner, the moon ___ risen.", "had", "has", "was", "is", "Earlier past completion uses Past Perfect 'had risen'."),
    q("When I met Dinithi last week, she ___ wearing a blue uniform.", "was", "is", "were", "has been", "Past description at a point in time takes 'was wearing'."),
    q("He ___ ill for three days before his parents took him to hospital.", "had been", "has been", "is", "was being", "State continuing up to a past event uses 'had been'."),
    q("The clock ___ twelve times just as the parade began.", "struck", "strike", "striked", "striking", "Irregular past of 'strike' is 'struck'."),
    q("The thirsty travellers ___ cool spring water from the stream.", "drank", "drink", "drunk", "drinking", "Simple Past of 'drink' is 'drank' ('drunk' is V3)."),
    q("Someone ___ the bell five minutes earlier than usual today.", "rang", "ring", "rung", "ringing", "Simple Past of 'ring' is 'rang' ('rung' is V3)."),
    q("He ___ a deep hole in the garden to plant a mango sapling.", "dug", "dig", "digged", "digging", "Irregular past of 'dig' is 'dug'."),
    q("She ___ her jacket on the wooden peg near the doorway.", "hung", "hang", "hanged", "hanging", "Past of 'hang' (an object) is 'hung'."),
    q("Nobody knew where the migratory birds had ___ for the winter.", "flown", "flew", "fly", "flowed", "Past participle of 'fly' after 'had' is 'flown'.")
  )
}
